/* --------------------------------------------------------------- projection */
/* mercY / mercLat imported from ../../../map/projection */
const TOPY = mercY(80), BOTY = mercY(-78);
const MAP_W = 360, MAP_H = TOPY - BOTY;
/* world space: wx = lon + 180 (0..360), wy = TOPY - mercY(lat) (0..MAP_H) */
const wxOf = (lon) => lon + 180;
const wyOf = (lat) => TOPY - mercY(lat);

/* ------------------------------------------------------------ coast decode */
const BCH = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz@_";
const BIX = (() => { const m = new Int16Array(128).fill(-1); for (let i = 0; i < BCH.length; i++) m[BCH.charCodeAt(i)] = i; return m; })();
const RINGS = COAST.split("|").map((s) => {
  const out = []; let i = 0, x = 0, y = 0;
  const rd = () => {
    let n = 0, sh = 0, d;
    do { d = BIX[s.charCodeAt(i++)]; n |= (d & 31) << sh; sh += 5; } while (d >= 32);
    return n & 1 ? -((n + 1) >> 1) : n >> 1;
  };
  while (i < s.length) {
    x += rd(); y += rd();
    out.push(wxOf(x / 20), wyOf(Math.max(-84, Math.min(84, y / 20))));
  }
  const a = new Float64Array(out);
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (let k = 0; k < a.length; k += 2) {
    if (a[k] < x0) x0 = a[k]; if (a[k] > x1) x1 = a[k];
    if (a[k + 1] < y0) y0 = a[k + 1]; if (a[k + 1] > y1) y1 = a[k + 1];
  }
  return { p: a, x0, x1, y0, y1 };
});

/* ------------------------------------------------- currents in world space */
/* Longitude is made continuous along each path, so a current that crosses the
   dateline keeps going instead of flying back across the map. */
const PATHS = CUR.map((c, idx) => {
  const w = c.w;
  const pts = [wxOf(w[0][0]), wyOf(w[0][1])];
  for (let i = 1; i < w.length; i++) {
    let d = w[i][0] - w[i - 1][0];
    if (d > 180) d -= 360; else if (d < -180) d += 360;
    pts.push(pts[pts.length - 2] + d, wyOf(w[i][1]));
  }
  let x0 = Infinity, x1 = -Infinity, y0 = Infinity, y1 = -Infinity;
  for (let k = 0; k < pts.length; k += 2) {
    if (pts[k] < x0) x0 = pts[k]; if (pts[k] > x1) x1 = pts[k];
    if (pts[k + 1] < y0) y0 = pts[k + 1]; if (pts[k + 1] > y1) y1 = pts[k + 1];
  }
  return { i: idx, p: new Float64Array(pts), x0, x1, y0, y1 };
});
const CBY = (i) => CUR[i];
const TOTAL = CUR.length;
const FAM_COUNT = {};
CUR.forEach((c) => { FAM_COUNT[c.f] = (FAM_COUNT[c.f] || 0) + 1; });

/* ------------------------------------------------------------------ geometry */
/* segDist imported from ../../../map/projection */
/* nearest approach of a world-space point to a path, wrapping longitude */
function nearestOn(path, wx, wy) {
  let best = { d: Infinity, x: 0, y: 0 };
  for (const shift of [-360, 0, 360]) {
    const x = wx + shift;
    if (x < path.x0 - 40 || x > path.x1 + 40) continue;
    for (let k = 0; k + 3 < path.p.length; k += 2) {
      const r = segDist(x, wy, path.p[k], path.p[k + 1], path.p[k + 2], path.p[k + 3]);
      if (r.d < best.d) best = { d: r.d, x: r.x - shift, y: r.y };
    }
  }
  return best;
}
/* haversine imported from ../../../map/projection */

/* ------------------------------------------------------------------- drawing */
/* Catmull-Rom through the waypoints, so a current reads as a flowing line
   rather than a chain of straight legs. */
function tracePath(ctx, xs, ys) {
  const n = xs.length;
  ctx.moveTo(xs[0], ys[0]);
  if (n === 2) { ctx.lineTo(xs[1], ys[1]); return; }
  for (let i = 0; i < n - 1; i++) {
    const x0 = xs[i > 0 ? i - 1 : 0], y0 = ys[i > 0 ? i - 1 : 0];
    const x1 = xs[i], y1 = ys[i], x2 = xs[i + 1], y2 = ys[i + 1];
    const x3 = xs[i + 2 < n ? i + 2 : n - 1], y3 = ys[i + 2 < n ? i + 2 : n - 1];
    ctx.bezierCurveTo(x1 + (x2 - x0) / 6, y1 + (y2 - y0) / 6,
      x2 - (x3 - x1) / 6, y2 - (y3 - y1) / 6, x2, y2);
  }
}
function arrowsAlong(ctx, xs, ys, every, col) {
  let acc = every * 0.55;
  ctx.fillStyle = col;
  for (let i = 0; i + 1 < xs.length; i++) {
    const dx = xs[i + 1] - xs[i], dy = ys[i + 1] - ys[i];
    const len = Math.hypot(dx, dy);
    if (len < 0.001) continue;
    let t = every - acc;
    while (t < len) {
      const x = xs[i] + (dx / len) * t, y = ys[i] + (dy / len) * t;
      const ux = dx / len, uy = dy / len, s = 4.6;
      ctx.beginPath();
      ctx.moveTo(x + ux * s, y + uy * s);
      ctx.lineTo(x - ux * s * 0.7 - uy * s * 0.62, y - uy * s * 0.7 + ux * s * 0.62);
      ctx.lineTo(x - ux * s * 0.7 + uy * s * 0.62, y - uy * s * 0.7 - ux * s * 0.62);
      ctx.closePath(); ctx.fill();
      t += every;
    }
    acc = (acc + len) % every;
  }
}

const MIN_Z = 1, MAX_Z = 18, TOL_PX = 22, TIE_PX = 6, CROWD_ZOOM = 2.2;
/* How close a tap has to be to count. Pixels alone would mean the drill got
   geographically stricter the further you zoomed in — a 200 km miss accepted
   at world view and refused at basin scale — which penalises the zooming that
   makes an answer precise in the first place. So the tolerance is the more
   generous of 22 px and a flat 250 km, and zooming can only ever help.
   Mercator is conformal, so a map-degree is 111.32 km * cos(lat) on the
   ground; the cosine is floored so the Arctic does not blow up. */
const KM_TOL = 250, KM_PER_DEG = 111.32;
const kmToWorld = (km, lat) => km / (KM_PER_DEG * Math.max(0.15, Math.cos(lat * Math.PI / 180)));

function MapView({ w, h, solved, target, mode, flash, mark, grat, labels, revealAll, onAnswer }) {
  const cvs = useRef(null);
  const stat = useRef(null);
  const box = useRef(null);
  const raf = useRef(0);
  const [view, setView] = useState({ z: 1, tx: 0, ty: 0, x: 200 });
  const g = useRef({ kind: null, x: 0, y: 0, moved: 0, d0: 0, z0: 1, cx: 0, cy: 0, tx0: 0, ty0: 0, last: 0 });
  const reduced = useRef(false);

  useEffect(() => {
    reduced.current = window.matchMedia
      && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  }, []);

  const base = Math.min(w / MAP_W, h / MAP_H);
  const scale = base * view.z;

  const clampView = useCallback((v) => {
    const s = base * v.z, mh = MAP_H * s;
    const ty = mh <= h ? (h - mh) / 2 : Math.min(0, Math.max(h - mh, v.ty));
    let tx = v.tx;
    const period = MAP_W * s;
    if (period > 0) tx = ((tx % period) + period) % period - period;  /* wrap */
    return { z: v.z, tx, ty };
  }, [base, h]);

  useEffect(() => { setView((v) => clampView(v)); }, [clampView]);

  const zoomAbout = useCallback((px, py, f) => {
    setView((v) => {
      const z = Math.max(MIN_Z, Math.min(MAX_Z, v.z * f));
      const k = z / v.z;
      return clampView({ z, tx: px - (px - v.tx) * k, ty: py - (py - v.ty) * k });
    });
  }, [clampView]);

  const tap = useCallback((px, py) => {
    const wx = (px - view.tx) / scale;
    const wy = (py - view.ty) / scale;
    if (wy < 0 || wy > MAP_H) { onAnswer(null); return; }
    const lon = ((wx % 360) + 360) % 360 - 180;
    const lat = mercLat(TOPY - wy);
    const tolWorld = Math.max(TOL_PX / scale, kmToWorld(KM_TOL, lat));
    const res = onAnswer({ lon, lat, wx: lon + 180, wy, tolWorld, ppw: scale });
    /* crowded water: close in on the spot the finger landed, so the next tap
       is one the chart can actually answer */
    if (res === "zoom") zoomAbout(px, py, CROWD_ZOOM);
  }, [view, scale, onAnswer, zoomAbout]);

  /* ------------------------------------------------- static layer: the sea */
  useEffect(() => {
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    if (!stat.current) stat.current = document.createElement("canvas");
    const cv = stat.current;
    cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
    const x = cv.getContext("2d");
    x.setTransform(dpr, 0, 0, dpr, 0, 0);
    x.fillStyle = C.page; x.fillRect(0, 0, w, h);
    const s = scale, tx = view.tx, ty = view.ty;
    x.fillStyle = C.ocean; x.fillRect(0, ty, w, MAP_H * s);

    if (grat) {
      x.strokeStyle = C.grat; x.lineWidth = 1; x.beginPath();
      for (let lat = -60; lat <= 75; lat += 15) {
        const py = wyOf(lat) * s + ty;
        if (py > -2 && py < h + 2) { x.moveTo(0, py); x.lineTo(w, py); }
      }
      for (let lon = -180; lon < 180; lon += 30) {
        for (let k = -1; k <= 2; k++) {
          const px = (wxOf(lon) + k * 360) * s + tx;
          if (px > -2 && px < w + 2) { x.moveTo(px, ty); x.lineTo(px, ty + MAP_H * s); }
        }
      }
      x.stroke();
      /* the equator, drawn as itself */
      x.strokeStyle = "#1d2a36"; x.beginPath();
      const eq = wyOf(0) * s + ty; x.moveTo(0, eq); x.lineTo(w, eq); x.stroke();
    }

    const k0 = Math.floor((0 - tx) / (360 * s)) - 1, k1 = Math.ceil((w - tx) / (360 * s));
    x.lineJoin = "round";
    for (let k = k0; k <= k1; k++) {
      const off = tx + k * 360 * s;
      for (const r of RINGS) {
        if (r.x1 * s + off < -2 || r.x0 * s + off > w + 2) continue;
        if (r.y1 * s + ty < -2 || r.y0 * s + ty > h + 2) continue;
        if ((r.x1 - r.x0) * s < 1.1 && (r.y1 - r.y0) * s < 1.1) continue;
        x.beginPath();
        x.moveTo(r.p[0] * s + off, r.p[1] * s + ty);
        for (let i = 2; i < r.p.length; i += 2) x.lineTo(r.p[i] * s + off, r.p[i + 1] * s + ty);
        x.closePath();
        x.fillStyle = C.land; x.fill();
        x.strokeStyle = C.coastline; x.lineWidth = 0.7; x.stroke();
      }
    }
  }, [w, h, scale, view, grat]);

  /* ------------------------------------------ animated layer: the currents */
  useEffect(() => {
    const cv = cvs.current; if (!cv) return;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    cv.width = Math.round(w * dpr); cv.height = Math.round(h * dpr);
    const ctx = cv.getContext("2d");
    const s = scale, ty = view.ty;

    const draw = (t) => {
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      ctx.clearRect(0, 0, w, h);
      if (stat.current) ctx.drawImage(stat.current, 0, 0, w, h);

      const k0 = Math.floor((0 - view.tx) / (360 * s)) - 1;
      const k1 = Math.ceil((w - view.tx) / (360 * s));

      for (const path of PATHS) {
        const i = path.i;
        const isTarget = i === target;
        const shown = revealAll || solved.has(i) || (mode === "name" && isTarget)
          || (flash && (flash.good === i || flash.bad === i));
        if (!shown) continue;
        const cur = CUR[i];
        let col = TEMP[cur.t].c, lw = 2.1, alpha = 1;
        if (mode === "name" && isTarget && !revealAll) { col = C.ivory; lw = 3; }
        if (flash && flash.good === i) { col = C.brass; lw = 3.4; }
        if (flash && flash.bad === i) { col = C.dim; lw = 2.6; }
        if (!isTarget && !flash && solved.has(i)) alpha = 0.92;

        for (let k = k0; k <= k1; k++) {
          const off = view.tx + k * 360 * s;
          if (path.x1 * s + off < -60 || path.x0 * s + off > w + 60) continue;
          if (path.y1 * s + ty < -60 || path.y0 * s + ty > h + 60) continue;
          const n = path.p.length / 2;
          const xs = new Array(n), ys = new Array(n);
          for (let q = 0; q < n; q++) { xs[q] = path.p[q * 2] * s + off; ys[q] = path.p[q * 2 + 1] * s + ty; }

          ctx.globalAlpha = alpha * 0.42;
          ctx.strokeStyle = col; ctx.lineWidth = lw; ctx.lineCap = "round";
          ctx.setLineDash([]); ctx.beginPath(); tracePath(ctx, xs, ys); ctx.stroke();

          /* the flow itself: dashes marching at the current's real speed */
          ctx.globalAlpha = alpha;
          ctx.setLineDash([7, 13]);
          ctx.lineDashOffset = -t * cur.sp * 0.055;
          ctx.beginPath(); tracePath(ctx, xs, ys); ctx.stroke();
          ctx.setLineDash([]);

          ctx.globalAlpha = alpha * 0.95;
          arrowsAlong(ctx, xs, ys, Math.max(90, 150 - s * 0.4), col);

          if (labels && !isTarget) {
            const mid = (n / 2) | 0;
            ctx.globalAlpha = 1;
            ctx.font = "500 10.5px ui-monospace, SFMono-Regular, Menlo, monospace";
            ctx.textAlign = "center";
            ctx.lineWidth = 3; ctx.strokeStyle = "rgba(7,13,19,.85)";
            ctx.strokeText(cur.n, xs[mid], ys[mid] - 8);
            ctx.fillStyle = "#cfd8e2"; ctx.fillText(cur.n, xs[mid], ys[mid] - 8);
            ctx.lineWidth = lw;
          }
        }
      }
      ctx.globalAlpha = 1; ctx.setLineDash([]);

      /* where the finger actually landed */
      if (mark) {
        for (let k = k0; k <= k1; k++) {
          const px = (mark.wx + k * 360) * s + view.tx, py = mark.wy * s + ty;
          if (px < -20 || px > w + 20) continue;
          ctx.strokeStyle = C.dim; ctx.lineWidth = 1.6;
          ctx.beginPath();
          ctx.moveTo(px - 5, py - 5); ctx.lineTo(px + 5, py + 5);
          ctx.moveTo(px + 5, py - 5); ctx.lineTo(px - 5, py + 5);
          ctx.stroke();
        }
      }

      if (!reduced.current) raf.current = requestAnimationFrame(() => draw((performance.now() / 1000)));
    };

    draw(reduced.current ? 0 : performance.now() / 1000);
    return () => cancelAnimationFrame(raf.current);
  }, [w, h, scale, view, solved, target, mode, flash, mark, labels, revealAll]);

  /* ----------------------------------------------------------- gestures */
  useEffect(() => {
    const el = box.current; if (!el) return;
    const rect = () => el.getBoundingClientRect();
    const dist = (t) => Math.hypot(t[0].clientX - t[1].clientX, t[0].clientY - t[1].clientY);
    const onBtn = (t) => t && t.closest && t.closest(".oc-mapbtn");

    const startPinch = (t, r) => {
      g.current.kind = "pinch"; g.current.d0 = dist(t); g.current.z0 = view.z;
      g.current.cx = (t[0].clientX + t[1].clientX) / 2 - r.left;
      g.current.cy = (t[0].clientY + t[1].clientY) / 2 - r.top;
    };
    const onStart = (e) => {
      if (onBtn(e.target)) return;
      const r = rect();
      if (e.touches.length >= 2) { startPinch([e.touches[0], e.touches[1]], r); e.preventDefault(); return; }
      const t = e.touches[0];
      g.current.kind = "maybe"; g.current.x = t.clientX; g.current.y = t.clientY;
      g.current.moved = 0; g.current.tx0 = view.tx; g.current.ty0 = view.ty;
    };
    const onMove = (e) => {
      if (g.current.kind === null) return;
      const r = rect();
      if (e.touches.length >= 2) {
        if (g.current.kind !== "pinch") startPinch([e.touches[0], e.touches[1]], r);
        const f = dist([e.touches[0], e.touches[1]]) / g.current.d0;
        const z = Math.max(MIN_Z, Math.min(MAX_Z, g.current.z0 * f));
        setView((v) => {
          const k = z / v.z;
          return clampView({ z, tx: g.current.cx - (g.current.cx - v.tx) * k, ty: g.current.cy - (g.current.cy - v.ty) * k });
        });
        e.preventDefault(); return;
      }
      if (g.current.kind === "pinch") return;
      const t = e.touches[0];
      const dx = t.clientX - g.current.x, dy = t.clientY - g.current.y;
      g.current.moved = Math.max(g.current.moved, Math.hypot(dx, dy));
      if (g.current.moved > 10) {
        g.current.kind = "pan";
        setView((v) => clampView({ z: v.z, tx: g.current.tx0 + dx, ty: g.current.ty0 + dy }));
        e.preventDefault();
      }
    };
    const onEnd = (e) => {
      if (onBtn(e.target)) { g.current.kind = null; return; }
      if (g.current.kind === "maybe" && g.current.moved <= 10) {
        const r = rect(), t = e.changedTouches[0];
        g.current.last = Date.now();
        tap(t.clientX - r.left, t.clientY - r.top);
      }
      g.current.kind = null;
    };
    const onWheel = (e) => {
      if (onBtn(e.target)) return;
      const r = rect();
      zoomAbout(e.clientX - r.left, e.clientY - r.top, e.deltaY < 0 ? 1.15 : 1 / 1.15);
      e.preventDefault();
    };
    el.addEventListener("touchstart", onStart, { passive: false });
    el.addEventListener("touchmove", onMove, { passive: false });
    el.addEventListener("touchend", onEnd);
    el.addEventListener("touchcancel", onEnd);
    el.addEventListener("wheel", onWheel, { passive: false });
    return () => {
      el.removeEventListener("touchstart", onStart);
      el.removeEventListener("touchmove", onMove);
      el.removeEventListener("touchend", onEnd);
      el.removeEventListener("touchcancel", onEnd);
      el.removeEventListener("wheel", onWheel);
    };
  }, [view, clampView, zoomAbout, tap]);

  const md = useRef(null);
  const isBtn = (t) => t && t.closest && t.closest(".oc-mapbtn");
  const onMouseDown = (e) => {
    if (isBtn(e.target)) return;
    md.current = { x: e.clientX, y: e.clientY, tx: view.tx, ty: view.ty, moved: 0 };
  };
  const onMouseMove = (e) => {
    const m = md.current; if (!m) return;
    const dx = e.clientX - m.x, dy = e.clientY - m.y;
    m.moved = Math.max(m.moved, Math.hypot(dx, dy));
    if (m.moved > 6) setView((v) => clampView({ z: v.z, tx: m.tx + dx, ty: m.ty + dy }));
  };
  const onMouseUp = (e) => {
    const m = md.current; md.current = null;
    if (isBtn(e.target)) return;
    if (!m || m.moved > 6) return;
    if (Date.now() - g.current.last < 600) return;
    const r = box.current.getBoundingClientRect();
    tap(e.clientX - r.left, e.clientY - r.top);
  };

  return (
    <div className="oc-mapwrap" ref={box}
      onMouseDown={onMouseDown} onMouseMove={onMouseMove} onMouseUp={onMouseUp}
      onMouseLeave={() => { md.current = null; }}
      role="img" aria-label="World ocean map. Currents stay hidden until you place them.">
      <canvas ref={cvs} style={{ width: w, height: h, display: "block", touchAction: "none", cursor: "crosshair" }} />
      <div className="oc-zoom">
        <button className="oc-mapbtn" aria-label="Zoom in" onClick={() => zoomAbout(w / 2, h / 2, 1.6)}>+</button>
        <button className="oc-mapbtn" aria-label="Zoom out" onClick={() => zoomAbout(w / 2, h / 2, 1 / 1.6)}>−</button>
      </div>
      {view.z > 1.02 && (
        <button className="oc-mapbtn oc-reset" onClick={() => setView(clampView({ z: 1, tx: 0, ty: 0 }))}>
          Whole ocean
        </button>
      )}
    </div>
  );
}

/* ========================================================================== */
/*  Session                                                                    */
/* ========================================================================== */

const CIRCUM = 40075;
const LEGS = [
  ["Set adrift, Florida Straits", 0], ["Cape Hatteras", 0.1], ["The Grand Banks", 0.22],
  ["Rockall Trough", 0.34], ["Canary upwelling", 0.46], ["Cape Agulhas", 0.58],
  ["The Roaring Forties", 0.72], ["Drake Passage", 0.86], ["The Sargasso", 0.95], ["Home water", 1],
];
/* shuffle imported from ../../../map/projection */
const allIds = CUR.map((_, i) => i);
const fmt = (n) => n.toLocaleString("en-US");
const knots = (cms) => (cms * 0.0194384).toFixed(1);

